452	      block.classList.add('wrong');
453	      block.querySelector('.feedback.wrong').classList.add('show');
454	      // reveal correct
455	      btns.forEach(b => {
456	        if (b.getAttribute('onclick') && b.getAttribute('onclick').includes('true')) {
457	          b.classList.add('reveal-correct');
458	        }
459	      });
460	      wrong++;
461	      document.getElementById('score-wrong').textContent = wrong;
462	    }
463	
464	    const answered = correct + wrong;
465	    document.getElementById('score-remaining').textContent = total - answered;
466	    document.getElementById('progress-fill').style.width = ((answered / total) * 100) + '%';
467	  }
468	
469	  function revealAnswer(btn) {
470	    const block = btn.closest('.recall-block');
471	    const answer = block.querySelector('.model-answer');
472	    answer.classList.toggle('show');
473	    btn.textContent = answer.classList.contains('show') ? 'Hide model answer' : 'Show model answer';
474	  }
475	</script>
476	</body>
